// generated by gemini-3.5-flash-lite for PR #5792 (round 0): flatten_deep_object
// intent: Verify that flattening a deeply nested object of 500 levels succeeds and yields the expected escaped path.
#include <nlohmann/json.hpp>
#include <iostream>
#include <string>

int main() {
    try {
        std::string s;
        int depth = 500;
        for (int i = 0; i < depth; ++i) s += "{\"a\":";
        s += "123";
        for (int i = 0; i < depth; ++i) s += "}";
        auto j = nlohmann::json::parse(s);
        auto flat = j.flatten();
        std::cout << flat.size() << std::endl;
        std::cout << flat.begin().key() << std::endl;
        std::cout << flat.begin().value() << std::endl;
    } catch (const std::exception& e) {
        std::cout << "EXCEPTION: " << e.what() << std::endl;
    }
}
